WITH filtered AS (SELECT *, LENGTH(account_type) AS account_type_length FROM accounts WHERE status IS DISTINCT FROM 'FROZEN' AND status IS NOT NULL) SELECT d.city, src.status, COUNT(*) AS cnt, SUM(src.balance) AS total_balance, MAX(src.account_type_length) AS max_account_type_length, GROUPING_ID() AS grouping_level FROM filtered src LEFT JOIN customers d ON src.customer_id = d.id GROUP BY CUBE (d.city, src.status);
